#if APP_TESTS
using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading;using System.Windows;using System.Windows.Controls;using System.Windows.Threading;
namespace FileCompass {
 public partial class FilePanel {
  internal void VerifyCompactTabWidths(Action<bool,string> check){UpdateLayout();check(activeTabFace.ActualWidth<=321,"active tab has a bounded natural width instead of filling the row");var path=FluentUiTests.Children<PathTextBlock>(crumbScroll).FirstOrDefault();if(CurrentPath.Length>50)check(path!=null,"long active path uses middle compaction");if(path!=null){check(path.Text.StartsWith(Path.GetPathRoot(CurrentPath),StringComparison.OrdinalIgnoreCase),"shortened active path retains drive root");check(path.Text.EndsWith(Path.GetFileName(CurrentPath.TrimEnd('\\')),StringComparison.Ordinal),"shortened active path retains final directory");check(path.ToolTip as string==CurrentPath,"shortened path tooltip retains full path");}}
  internal double ActiveTabWidth {get{return activeTabFace.ActualWidth;}}
  internal void VerifyInlineTabRow(Action<bool,string> check){UpdateLayout();var star=FluentUiTests.Children<Button>(this).Single(x=>(x.Content as string)=="★");var starY=star.TransformToAncestor(this).Transform(new Point(0,star.ActualHeight/2)).Y;var tabsY=tabRow.TransformToAncestor(this).Transform(new Point(0,tabRow.ActualHeight/2)).Y;check(Math.Abs(starY-tabsY)<3,"tab strip and bookmark picker share one row");check(panelPathRow.ActualHeight<=35&&activeTabFace!=null&&activeTabFace.Child==crumbScroll,"active tab embeds breadcrumbs without an extra path row");}
 }
 internal static class InlineTabsTests {
  internal static int Run(string root){Directory.CreateDirectory(root);var checks=new List<string>();MainWindow w=null;string motif=AppearanceTheme.Motif;Action<bool,string> check=(yes,text)=>{if(!yes)throw new Exception(text);checks.Add(text);};try{SynchronizationContext.SetSynchronizationContext(new DispatcherSynchronizationContext(Dispatcher.CurrentDispatcher));L.ChangeLanguage("cs-CZ");FluentTheme.Ensure();AppearanceTheme.Apply("Light");string home=Directory.CreateDirectory(Path.Combine(root,"Dokumenty")).FullName;string other=Directory.CreateDirectory(Path.Combine(root,"Fotografie")).FullName;foreach(string theme in new[]{"Original","Balanced"}){AppearanceTheme.SetMotif(theme);var prefs=new ProgramSettings{LeftFolder=home,RightFolder=home,SaveTabsOnExit=true};prefs.Save();w=new MainWindow(null,prefs){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};w.Show();NavigationTests.WaitPanels(w);var panels=FluentUiTests.Children<FilePanel>(w).ToArray();var left=panels[0];var right=panels[1];
    for(int i=0;i<24;i++)w.StoreFolderBookmark("Dokumenty "+i,"Práce",left);check(w.BookmarkCount==24&&left.TabCount==1&&right.TabCount==1,theme+": saving many bookmarks does not open tabs");
    NavigationTests.Wait(w.OpenBookmarkTab(new FavoriteLocation{Name="Fotografie",Left=other,LeftLocation=new SavedTab{Path=other}}));check(left.TabCount==2&&left.CurrentPath==other&&right.TabCount==1,theme+": bookmark opens one tab in the selected panel");NavigationTests.Wait(right.OpenLocationTab(new SavedTab{Path=other}));NavigationTests.Wait(right.OpenLocationTab(new SavedTab{Path=home}));w.UpdateLayout();left.VerifyInlineTabRow(check);right.VerifyInlineTabRow(check);left.VerifyCompactTabWidths(check);right.VerifyCompactTabWidths(check);check(left.TabCount==2&&right.TabCount==3&&w.BookmarkCount==24,theme+": two left and three right tabs are independent of 24 saved bookmarks");NextStageTests.Draw(w,Path.Combine(root,theme+"-inline-tabs.png"));
    var saved=ProgramSettings.Load();check(saved.Favorites.Count==24&&saved.LeftTabs.Length==2&&saved.RightTabs.Length==3,theme+": bookmarks and open tabs are serialized separately");w.Close();w=null;w=new MainWindow(null,saved){Left=-18000,Top=-18000,ShowActivated=false,WindowStartupLocation=WindowStartupLocation.Manual};w.Show();NavigationTests.WaitPanels(w);panels=FluentUiTests.Children<FilePanel>(w).ToArray();left=panels[0];right=panels[1];check(left.TabCount==2&&right.TabCount==3&&w.BookmarkCount==24,theme+": restart restores only open tabs and keeps all saved bookmarks");w.UpdateLayout();left.VerifyCompactTabWidths(check);right.VerifyCompactTabWidths(check);left.CloseTab(1);NavigationTests.Wait(left.TabNavigationTask);check(left.TabCount==1&&w.BookmarkCount==24,theme+": closing a tab does not remove its saved bookmark");left.RestoreTabs(new[]{new SavedTab{Path=Path.GetPathRoot(home)},new SavedTab{Path=Path.GetPathRoot(home)}},1);NavigationTests.Wait(left.NavigationTask);w.UpdateLayout();check(left.ActiveTabWidth<=110,theme+": root tab stays as compact as neighboring root tab");NextStageTests.Draw(w,Path.Combine(root,theme+"-root-tabs.png"));
    var missing=Path.Combine(root,"missing-"+theme);NavigationTests.Wait(w.OpenBookmarkTab(new FavoriteLocation{Name="Chybí",Left=missing,LeftLocation=new SavedTab{Path=missing}}));check(left.HasUnavailableTab&&left.SaveTabs()[left.CurrentTabIndex].Path==missing,theme+": missing bookmark target remains explicit in its new tab");w.Close();w=null;
   }File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"PASS: "+checks.Count+" checks"}));return 0;
  }catch(Exception ex){File.WriteAllLines(Path.Combine(root,"result.txt"),checks.Concat(new[]{"FAIL: "+ex}));return 1;}finally{if(w!=null)w.Close();AppearanceTheme.SetMotif(motif);}}
 }
}
#endif
